pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(address from, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(from != address(0));
        StrictTransferFromValidator validator = new StrictTransferFromValidator();
        validator.setApprovalForAll(from, true);
        bool ok;
        try c.transfer(from, address(validator), _tos, v) returns (bool result) { ok = result; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract StrictTransferFromValidator {
    mapping(address => bool) public approved;
    function setApprovalForAll(address sender, bool status) external {
        approved[sender] = status;
    }
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        require(approved[sender], "sender not approved");
        return true;
    }
}
